// Parse Rattle deal alerts. Deal fields live in the message BLOCKS (and
// attachments), not the top-level text — gather everything, decode HTML
// entities, then find the *Name:* line. Returns the worker payload.
function collect(node, acc) {
  if (node == null) return;
  if (Array.isArray(node)) { node.forEach(n => collect(n, acc)); return; }
  if (typeof node === 'object') {
    if (typeof node.text === 'string') acc.push(node.text);
    else if (node.text && typeof node.text.text === 'string') acc.push(node.text.text);
    collect(node.blocks, acc);
    collect(node.elements, acc);
    collect(node.attachments, acc);
    collect(node.fields, acc);
  }
}

const out = [];
for (const item of $input.all()) {
  const m = item.json;
  const parts = [];
  if (typeof m.text === 'string') parts.push(m.text);
  collect(m.blocks, parts);
  collect(m.attachments, parts);
  const text = parts.join('\n')
    .replace(/&gt;/g, '>').replace(/&lt;/g, '<').replace(/&amp;/g, '&');
  const nameMatch = text.match(/\*Name:\*\s*(.+)/);
  if (!nameMatch) continue; // not a deal alert -> skip quietly
  out.push({ json: {
    channel_id: m.channel,
    thread_ts: m.thread_ts || m.ts,
    text,
  }});
}
return out;
